export TZ=UTC; date -u +%TZ
timeout 60 srun --jobid=173051 --overlap -n1 --mem=0 bash -c 'cg=$(cat /proc/self/cgroup | head -1 | cut -d: -f3); d=/sys/fs/cgroup$cg; for i in 1 2 3 4 5; do d=$(dirname $d); echo "$d cur=$(cat $d/memory.current 2>/dev/null) max=$(cat $d/memory.max 2>/dev/null) $(grep -E "^(anon|file) " $d/memory.stat 2>/dev/null | tr "\n" " ")"; ls -d $d/step_* 2>/dev/null | tr "\n" " "; echo; done; B=$(ls -d /sys/fs/cgroup/system.slice/slurmstepd.scope/job_173051/step_batch 2>/dev/null); echo B=$B; [ -n "$B" ] && echo "batch cur=$(cat $B/memory.current) $(grep -E "^(anon|file) " $B/memory.stat | tr "\n" " ")"' 2>&1 | head -20
